/**
 * A verification-code field drawn as separate digit cells (`design/components/otp-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/otp-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  cell,
  derived,
  elementRef,
  fieldValue,
  mountEffect,
  presence,
  useMember,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/controls/otp-input.module.css'

export type OTPLength = NonNullable<OTPInputProps['length']>

/** A verification-code field drawn as separate digit cells: the inputs it takes, by the React member's prop names. */
export interface OTPInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  /**
   * Usually set by FormField, for example for "That code didn't match".
   */
  invalid?: boolean
  /**
   * The code length, 4 or 6, which are the lengths real code systems use.
   */
  length?: 4 | 6
  /**
   * Set directly on the real input, so no hidden input is needed.
   */
  name?: string
  /**
   * Digits only. Every write path filters and truncates to `length`.
   */
  value?: string
}

/** A verification-code field drawn as separate digit cells. */
@Component({
  selector: 'pm-otp-input',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref],
  // prettier-ignore
  template: `<div
[attr.class]="e1()"
[attr.data-invalid]="e2()"
[attr.data-disabled]="e3()"
data-member="otp-input"
><!-- field -->
<input
[attr.class]="e4()"
type="text"
[value]="e5()"
[attr.disabled]="e6()"
[attr.name]="e7()"
[attr.id]="e8()"
inputmode="numeric"
autocomplete="one-time-code"
spellcheck="false"
autocapitalize="off"
autocorrect="off"
[attr.maxlength]="e9()"
[attr.aria-label]="e10()"
[attr.aria-labelledby]="e11()"
[attr.aria-describedby]="e12()"
[attr.aria-required]="e13()"
[attr.aria-invalid]="e14()"
(input)="h1($event)"
(paste)="h2($event)"
(keydown)="h3($event)"
(select)="h4($event)"
(mouseup)="h5($event)"
(keyup)="h6($event)"
(focus)="h7($event)"
(blur)="h8()"
[pmRef]="field"
/>
@for (index of e15(); track e16(index)) {<!-- cell -->
<span
[attr.class]="e17()"
aria-hidden="true"
[attr.data-filled]="e18(index)"
[attr.data-caret]="e19(index)"
>@if (e20(index)) {@for (digit of e21(index); track $index) {<span
[attr.class]="e22(index)"
>{{ e23(index, digit) }}</span>}}</span>}</div>`,
})
export class OTPInput {
  static readonly controlKind = 'field'
  readonly ariaDescribedby = input<OTPInputProps['aria-describedby']>(undefined, {
    alias: 'aria-describedby',
  })
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  readonly ariaLabel = input<OTPInputProps['aria-label']>(undefined, { alias: 'aria-label' })
  readonly ariaLabelledby = input<OTPInputProps['aria-labelledby']>(undefined, {
    alias: 'aria-labelledby',
  })
  readonly ariaRequired = input<OTPInputProps['aria-required']>(undefined, {
    alias: 'aria-required',
  })
  readonly defaultValue = input<OTPInputProps['defaultValue']>(undefined)
  readonly disabled = input<
    Exclude<OTPInputProps['disabled'], undefined>,
    OTPInputProps['disabled']
  >(false, {
    transform: (value: OTPInputProps['disabled']) => (value === undefined ? false : value),
  })
  readonly id = input<OTPInputProps['id']>(undefined)
  /**
   * Usually set by FormField, for example for "That code didn't match".
   */
  readonly invalid = input<Exclude<OTPInputProps['invalid'], undefined>, OTPInputProps['invalid']>(
    false,
    { transform: (value: OTPInputProps['invalid']) => (value === undefined ? false : value) },
  )
  /**
   * The code length, 4 or 6, which are the lengths real code systems use.
   */
  readonly length = input<Exclude<OTPInputProps['length'], undefined>, OTPInputProps['length']>(6, {
    transform: (value: OTPInputProps['length']) => (value === undefined ? 6 : value),
  })
  /**
   * Set directly on the real input, so no hidden input is needed.
   */
  readonly name = input<OTPInputProps['name']>(undefined)
  /**
   * Digits only. Every write path filters and truncates to `length`.
   */
  readonly value = input<OTPInputProps['value']>(undefined)
  /**
   * Never reports a non-digit.
   */
  readonly onChange = output<string>({ alias: 'change' })
  /**
   * Fires once, after `onChange`, when the code becomes full. Apps that want to verify without a
   * Verify button submit from here.
   */
  readonly onComplete = output<string>({ alias: 'complete' })
  protected readonly $ = useMember({
    kind: OTPInput.controlKind,
    events: ['change', 'complete'],
    props: {
      'aria-describedby': () => this.ariaDescribedby(),
      'aria-label': () => this.ariaLabel(),
      'aria-labelledby': () => this.ariaLabelledby(),
      'aria-required': () => this.ariaRequired(),
      defaultValue: () => this.defaultValue(),
      disabled: () => this.disabled(),
      id: () => this.id(),
      invalid: () => this.invalid(),
      length: () => this.length(),
      name: () => this.name(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uncontrolled = cell(() =>
    (this.$p.defaultValue ?? '').replace(/\D/g, '').slice(0, this.$p.length),
  )
  protected readonly focused = cell(() => false)
  protected readonly field = elementRef<HTMLElement>()
  protected readonly code = derived(() =>
    (this.$p.value ?? this.uncontrolled.value).replace(/\D/g, '').slice(0, this.$p.length),
  )
  protected readonly caretIndex = derived(() =>
    this.code.value.length === this.$p.length ? this.$p.length - 1 : this.code.value.length,
  )
  protected readonly cells = derived(() =>
    Array.from({ length: this.$p.length }, (_, index) => index),
  )
  protected readonly commit = derived(
    () => (next: string) =>
      ((before: string) => (
        (this.uncontrolled.value = next),
        next !== before && this.$.emit(this.onChange, 'onChange', next),
        next.length === this.$p.length &&
          before.length < this.$p.length &&
          this.$.emit(this.onComplete, 'onComplete', next)
      ))(this.code.value),
  )
  protected readonly receive = derived(
    () => (event: Event) =>
      ((input: HTMLInputElement) => (
        this.commit.value(input.value.replace(/\D/g, '').slice(0, this.$p.length)),
        (input.value = this.code.value)
      ))(event.target as HTMLInputElement),
  )
  protected readonly receivePaste = derived(
    () => (event: ClipboardEvent) => (
      event.preventDefault(),
      this.commit.value(
        (event.clipboardData?.getData('text') ?? '').replace(/\D/g, '').slice(0, this.$p.length),
      ),
      ((event.target as HTMLInputElement).value = this.code.value)
    ),
  )
  protected readonly pinCaret = derived(
    () => (event: Event) =>
      ((node: HTMLInputElement) =>
        (node.selectionStart !== this.code.value.length ||
          node.selectionEnd !== this.code.value.length) &&
        node.setSelectionRange(this.code.value.length, this.code.value.length))(
        event.currentTarget as HTMLInputElement,
      ),
  )
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.invalid ? '' : undefined
  }

  protected e3() {
    return this.$p.disabled ? '' : undefined
  }

  protected e4() {
    return styles.input
  }

  protected e5() {
    return fieldValue(this.code.value)
  }

  protected e6() {
    return presence(this.$p.disabled)
  }

  protected e7() {
    return this.$p.name
  }

  protected e8() {
    return this.$p.id
  }

  protected e9() {
    return this.$p.length
  }

  protected e10() {
    return this.$p['aria-label']
  }

  protected e11() {
    return this.$p['aria-labelledby']
  }

  protected e12() {
    return this.$p['aria-describedby']
  }

  protected e13() {
    return this.$p['aria-required']
  }

  protected e14() {
    return this.$p.invalid ? true : undefined
  }

  protected h1($event: Event): void {
    this.receive.value($event)
  }

  protected h2($event: ClipboardEvent): void {
    this.receivePaste.value($event)
  }

  protected h3($event: KeyboardEvent): void {
    if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes($event.key)) {
      $event.preventDefault()
    }
  }

  protected h4($event: Event): void {
    this.pinCaret.value($event)
  }

  protected h5($event: MouseEvent): void {
    this.pinCaret.value($event)
  }

  protected h6($event: KeyboardEvent): void {
    this.pinCaret.value($event)
  }

  protected h7($event: FocusEvent): void {
    void ((this.focused.value = true), this.pinCaret.value($event))
  }

  protected h8(): void {
    this.focused.value = false
  }

  e15() {
    return this.cells.value
  }

  protected e16(index: Each<ReturnType<OTPInput['e15']>>) {
    return index
  }

  protected e17() {
    return styles.cell
  }

  protected e18(index: Each<ReturnType<OTPInput['e15']>>) {
    return this.code.value[index] !== undefined ? '' : undefined
  }

  protected e19(index: Each<ReturnType<OTPInput['e15']>>) {
    return this.focused.value && index === this.caretIndex.value ? '' : undefined
  }

  protected e20(index: Each<ReturnType<OTPInput['e15']>>) {
    return this.code.value[index] !== undefined
  }

  e21(index: Each<ReturnType<OTPInput['e15']>>) {
    if (!(this.code.value[index] !== undefined)) return undefined as never
    return [this.code.value[index]]
  }

  protected e22(index: Each<ReturnType<OTPInput['e15']>>) {
    if (!(this.code.value[index] !== undefined)) return undefined as never
    return styles.digit
  }

  protected e23(
    index: Each<ReturnType<OTPInput['e15']>>,
    digit: Each<ReturnType<OTPInput['e21']>>,
  ) {
    if (!(this.code.value[index] !== undefined)) return undefined as never
    return digit
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'OTPInput',
      element: () => this.field.value,
      state: () => ({
        value: this.code.value,
        disabled: this.$p.disabled,
        invalid: this.$p.invalid,
      }),
      actions: {},
      secret: ['value'],
    })
    this.release1 = () => {
      ran()
    }
  }
}
